int SPI_init()
{
    spi_fd = open(SPI_DEV, O_RDWR | O_NONBLOCK);
    if (spi_fd < 0) {
        perror("open spi");
        return -1;
    }
    uint8_t mode = SPI_MODE_3;        // CPOL=0, CPHA=0  
    uint8_t bits = 8;                 // 8 位数据  
    uint32_t speed = 40000000;        // 40 MHz  

    ioctl(spi_fd, SPI_IOC_WR_MODE, &mode);
    ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &(uint8_t){8});
    ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed);

    return 1;
}




void LCD_WR_REG(uint8_t data)
{
	gpio_set(LCDPin_RS,0);
    gpio_set(LCDPin_CS,0);
    spi_w(&data, 1);
	gpio_set(LCDPin_CS,1);
}

void LCD_WR_DATA8(uint8_t data)
{
	gpio_set(LCDPin_RS,1);
    gpio_set(LCDPin_CS,0);
    spi_w(&data, 1);
    gpio_set(LCDPin_CS,1);
}

void LCD_WR_DATA(uint16_t data)
{
    LCD_WR_DATA8(data>>8);
    LCD_WR_DATA8(data);
}


int spi_w_16(uint16_t* tx,int len)
{
    uint8_t bits = 16;
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = 0,
        .len    = len * 2,
        .speed_hz = 40000000,
        .bits_per_word = bits,  
        // .cs_change = 0,  
    };
    ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
}


int spi_w(uint8_t* tx,int len)
{
    uint8_t bits = 8;
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = 0,
        .len    = len,
        .speed_hz = 40000000,
        .bits_per_word = bits,  
        // .cs_change = 0,  
    };
    ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
}



void LCD_Simple_inition()
{
    usleep(1000*50);
    gpio_set(LCDPin_RST,1);
    usleep(1000*50);
    gpio_set(LCDPin_RST,0);
    gpio_set(LCDPin_CS,1);	
    usleep(1000*50);
	gpio_set(LCDPin_RST,1);
	usleep(1000*150);

    LCD_WR_REG(0x01);
    usleep(1000*150);

	
	LCD_WR_REG(0xfe);			
	LCD_WR_DATA8(0x01);
	LCD_WR_REG(0x6A);			
	LCD_WR_DATA8(0x21);
	LCD_WR_REG(0xfe);			
	LCD_WR_DATA8(0x00);//CMD1 command
				
	LCD_WR_REG(0xC4);			                //NEW  ADD
	LCD_WR_DATA8(0x80);//CMD1 command     //NEW  ADD
	
    // LCD_WR_REG(0x67);
    // LCD_WR_DATA8(0x00); 

    // LCD_WR_REG(0x36);
    // LCD_WR_DATA8(0x00);  // MV=1, MX=1, MY=0, RGB 顺序（具体看你模组）

// // 设 CASET：列起始/结束（物理列方向，MV=1 后对应逻辑行）
// LCD_WR_REG(0x2A);
// LCD_WR_DATA8(0x00);
// LCD_WR_DATA8(0x00);       // 列起始 = 0
// LCD_WR_DATA8(0x00);
// LCD_WR_DATA8(0x7D);       // 列结束 = 125（0x7D = 125，对应 126 列）

// // 设 RASET：行起始/结束（物理行方向，MV=1 后对应逻辑列）
// LCD_WR_REG(0x2B);
// LCD_WR_DATA8(0x00);
// LCD_WR_DATA8(0x00);       // 行起始 = 0
// LCD_WR_DATA8(0x01);
// LCD_WR_DATA8(0x25);       // 行结束 = 293（0x125 = 293，对应 294 行）


	LCD_WR_REG(0x35);			
	LCD_WR_DATA8(0x00);
			
	LCD_WR_REG(0x51);			
	LCD_WR_DATA8(0xff);
			
	LCD_WR_REG(0x3A);
	LCD_WR_DATA8(0x05);//默认888格式，看平台送数据格式，如果不是888格式就需要下3Ah

    LCD_WR_REG(0x20);

	LCD_WR_REG(0x11);		
	///Delay(150);//时间不能过短，否则刷屏会顿挫
	usleep(1000*150);
			
	LCD_WR_REG(0x29);			

    gpio_set(LCDPin_CS,1);	

}

void LCD_init()
{
    gpio_init(LCDPin_RS, GPIO_MODE_OUTPUT);
    gpio_init(LCDPin_RST, GPIO_MODE_OUTPUT);
    gpio_init(LCDPin_CS, GPIO_MODE_OUTPUT);

    LCD_Simple_inition();
}





void LCD_SPI_SetDisplayWindow(u16 x0, u16 x1, u16 y0, u16 y1)
{            //此函数非常重要
    LCD_WR_REG(0x2A); //Column Adress Setting
    LCD_WR_DATA8(x0>>8);
    LCD_WR_DATA8(x0);
    LCD_WR_DATA8(x1>>8);
    LCD_WR_DATA8(x1);

	
    LCD_WR_REG(0x2B); //Row Adress Setting 
    LCD_WR_DATA8(y0>>8);
    LCD_WR_DATA8(y0);
    LCD_WR_DATA8(y1>>8);
    LCD_WR_DATA8(y1);
}

void LCD_SPI_WriteRAM_Prepare()
{ 
    LCD_WR_REG(0x2c);
}


void  showpic_a()
{  
	vu32 index;
	vu32 size = XDP * YDP*2;
	
    LCD_SPI_SetDisplayWindow(0,XDP-1,0,YDP-1);
    LCD_SPI_WriteRAM_Prepare();	
        
    gpio_set(LCDPin_CS,0);
    gpio_set(LCDPin_RS,1);

    int package_size = 4096;
    int package_num = sizeof(gImage_1)/package_size;
    int i;
    for(i=0;i<package_num;i++)
    {
        spi_w(&gImage_1[i*package_size], package_size);
    }
    spi_w(&gImage_1[i*package_size], sizeof(gImage_1)%package_size);

    gpio_set(LCDPin_CS,1);
}



